// bbx fixture: MCP stdio server that completes the handshake and lists one tool,
// but never answers tools/call.
import readline from 'node:readline';
const send = (m) => process.stdout.write(JSON.stringify(m) + '\n');
readline.createInterface({ input: process.stdin }).on('line', (line) => {
  let r; try { r = JSON.parse(line); } catch { return; }
  if (r.id === undefined) return;
  if (r.method === 'initialize') send({ jsonrpc: '2.0', id: r.id, result: { protocolVersion: r.params?.protocolVersion ?? '2024-11-05', capabilities: { tools: {} }, serverInfo: { name: 'bbx-hang', version: '1.0.0' } } });
  else if (r.method === 'tools/list') send({ jsonrpc: '2.0', id: r.id, result: { tools: [{ name: 'stall', description: 'Never returns.', inputSchema: { type: 'object', properties: {}, additionalProperties: false } }] } });
  else if (r.method === 'tools/call') { /* never answer */ }
  else send({ jsonrpc: '2.0', id: r.id, result: {} });
});
